  const transportPartnerScopeLookup = useMemo(() => {
    const scopesByPartner = new Map<string, Map<string, number>>();
    filteredTransportAuditEntries.forEach((entry) => {
      const scopeBucket = scopesByPartner.get(entry.appLabel) ?? new Map<string, number>();
      scopeBucket.set(entry.scopeLabel, (scopeBucket.get(entry.scopeLabel) ?? 0) + 1);
      scopesByPartner.set(entry.appLabel, scopeBucket);
    });

    return new Map(
      [...scopesByPartner.entries()].map(([partnerLabel, scopeBucket]) => [
        partnerLabel,
        [...scopeBucket.entries()].sort((left, right) => right[1] - left[1])[0]?.[0] ?? '',
      ])
    );
  }, [filteredTransportAuditEntries]);
  const transportScopeAnalytics = useMemo(() => {
    const byScope = new Map<
      string,
      {
        scopeLabel: string;
        scopeType: 'region' | 'useCase' | 'other';
        scopeValue: string;
        total: number;
        opened: number;
        favorites: number;
        defaults: number;
        partners: Map<string, number>;
      }
    >();

    filteredTransportAuditEntries.forEach((entry) => {
      const scopeTarget = getTransportScopeTarget(entry.scopeLabel);
      const bucket = byScope.get(entry.scopeLabel) ?? {
        scopeLabel: entry.scopeLabel,
        scopeType: scopeTarget?.scopeType ?? 'other',
        scopeValue: scopeTarget?.scopeValue ?? entry.scopeLabel,
        total: 0,
        opened: 0,
        favorites: 0,
        defaults: 0,
        partners: new Map<string, number>(),
      };
      bucket.total += 1;
      if (entry.action === 'opened') bucket.opened += 1;
      if (entry.action === 'favorite_saved') bucket.favorites += 1;
      if (entry.action === 'default_saved') bucket.defaults += 1;
      bucket.partners.set(entry.appLabel, (bucket.partners.get(entry.appLabel) ?? 0) + 1);
      byScope.set(entry.scopeLabel, bucket);
    });

    const scopes = [...byScope.values()]
      .map((entry) => ({
        ...entry,
        partnerCount: entry.partners.size,
        topPartner: [...entry.partners.entries()].sort((left, right) => right[1] - left[1])[0]?.[0] ?? null,
        openRate: entry.total > 0 ? Math.round((entry.opened / entry.total) * 100) : 0,
        preferenceRate: entry.total > 0 ? Math.round(((entry.favorites + entry.defaults) / entry.total) * 100) : 0,
      }))
      .sort((left, right) => right.total - left.total || right.opened - left.opened);

    return {
      scopes,
      topRegion: scopes.find((entry) => entry.scopeType === 'region') ?? null,
      topUseCase: scopes.find((entry) => entry.scopeType === 'useCase') ?? null,
    };
  }, [filteredTransportAuditEntries]);
  const transportScopeTrend = useMemo(() => {
    const focusScopes = [
      transportScopeAnalytics.topRegion?.scopeLabel ?? null,
      transportScopeAnalytics.topUseCase?.scopeLabel ?? null,
    ].filter((value): value is string => Boolean(value));

    const days = Array.from({ length: 7 }, (_, index) => {
      const date = new Date();
      date.setHours(0, 0, 0, 0);
      date.setDate(date.getDate() - (6 - index));
      return {
        key: date.toISOString().slice(0, 10),
        label: formatTrendDayLabel(date),
        totals: new Map<string, number>(focusScopes.map((scope) => [scope, 0])),
      };
    });

    const byDay = new Map(days.map((day) => [day.key, day]));
    filteredTransportAuditEntries.forEach((entry) => {
      if (!focusScopes.includes(entry.scopeLabel)) return;
      const createdAt = new Date(entry.createdAt);
      if (Number.isNaN(createdAt.getTime())) return;
      createdAt.setHours(0, 0, 0, 0);
      const bucket = byDay.get(createdAt.toISOString().slice(0, 10));
      if (!bucket) return;
      bucket.totals.set(entry.scopeLabel, (bucket.totals.get(entry.scopeLabel) ?? 0) + 1);
    });

    const series = days.map((day) => ({
      key: day.key,
      label: day.label,
      values: focusScopes.map((scopeLabel) => ({
        scopeLabel,
        total: day.totals.get(scopeLabel) ?? 0,
      })),
    }));

    return {
      series,
      focusScopes,
      maxTotal: Math.max(1, ...series.flatMap((day) => day.values.map((value) => value.total))),
    };
  }, [filteredTransportAuditEntries, transportScopeAnalytics.topRegion?.scopeLabel, transportScopeAnalytics.topUseCase?.scopeLabel]);
  const transportScreenAnalytics = useMemo(() => {
    const aiTransportEntries = filteredAuditEntries.filter((entry) => entry.recommendedRoute === '/transport');
    const byScreen = new Map<
      string,
      {
        screen: string;
        aiDirected: number;
        hubOpened: number;
        partnerOpened: number;
        aiMentioned: number;
        partners: Map<string, number>;
      }
    >();

    aiTransportEntries.forEach((entry) => {
      const bucket = byScreen.get(entry.screen) ?? {
        screen: entry.screen,
        aiDirected: 0,
        hubOpened: 0,
        partnerOpened: 0,
        aiMentioned: 0,
        partners: new Map<string, number>(),
      };
      bucket.aiDirected += 1;
      if (didOpenTransportHub(entry)) bucket.hubOpened += 1;
      const mentionedLabel = getMentionedTransportPartnerLabel(entry);
      if (mentionedLabel) {
        bucket.aiMentioned += 1;
        bucket.partners.set(mentionedLabel, (bucket.partners.get(mentionedLabel) ?? 0) + 1);
      }
      const openedLabel = getOpenedTransportPartnerLabel(entry);
      if (openedLabel) {
        bucket.partnerOpened += 1;
        bucket.partners.set(openedLabel, (bucket.partners.get(openedLabel) ?? 0) + 1);
      }
      byScreen.set(entry.screen, bucket);
    });

    return [...byScreen.values()]
      .map((entry) => ({
        ...entry,
        hubRate: entry.aiDirected > 0 ? Math.round((entry.hubOpened / entry.aiDirected) * 100) : 0,
        partnerRate: entry.hubOpened > 0 ? Math.round((entry.partnerOpened / entry.hubOpened) * 100) : 0,
        mentionRate: entry.aiDirected > 0 ? Math.round((entry.aiMentioned / entry.aiDirected) * 100) : 0,
        topPartner: [...entry.partners.entries()].sort((left, right) => right[1] - left[1])[0]?.[0] ?? null,
      }))
      .sort((left, right) => right.aiDirected - left.aiDirected);
  }, [filteredAuditEntries]);
  const transportAiChoiceAnalytics = useMemo(() => {
    const aiTransportEntries = filteredAuditEntries.filter((entry) => entry.recommendedRoute === '/transport');
    let mentioned = 0;
    let matched = 0;
    let mismatched = 0;
    let unresolved = 0;

    aiTransportEntries.forEach((entry) => {
      const mentionedLabel = getMentionedTransportPartnerLabel(entry);
      if (!mentionedLabel) return;
      mentioned += 1;
      const openedLabel = getOpenedTransportPartnerLabel(entry);
      if (!openedLabel) {
        unresolved += 1;
        return;
      }
      if (openedLabel === mentionedLabel) {
        matched += 1;
      } else {
        mismatched += 1;
      }
    });

    return {
      mentioned,
      matched,
      mismatched,
      unresolved,
      matchRate: mentioned > 0 ? Math.round((matched / mentioned) * 100) : 0,
    };
  }, [filteredAuditEntries]);
  const transportScopeMatchAnalytics = useMemo(() => {
    const aiTransportEntries = filteredAuditEntries.filter((entry) => entry.recommendedRoute === '/transport');
    const byScope = new Map<
      string,
      {
        scopeLabel: string;
        directed: number;
        compared: number;
        matched: number;
        mismatched: number;
        unresolved: number;
        partners: Map<string, number>;
      }
    >();

    aiTransportEntries.forEach((entry) => {
      const scopeLabels = getMentionedTransportScopeLabels(entry);
      if (scopeLabels.length === 0) return;
      const mentionedPartner = getMentionedTransportPartnerLabel(entry);
      const openedPartner = getOpenedTransportPartnerLabel(entry);

      scopeLabels.forEach((scopeLabel) => {
        const bucket = byScope.get(scopeLabel) ?? {
          scopeLabel,
          directed: 0,
          compared: 0,
          matched: 0,
          mismatched: 0,
          unresolved: 0,
          partners: new Map<string, number>(),
        };
        bucket.directed += 1;
        if (mentionedPartner) {
          bucket.compared += 1;
          bucket.partners.set(mentionedPartner, (bucket.partners.get(mentionedPartner) ?? 0) + 1);
          if (!openedPartner) bucket.unresolved += 1;
          else if (openedPartner === mentionedPartner) bucket.matched += 1;
          else bucket.mismatched += 1;
        }
        byScope.set(scopeLabel, bucket);
      });
    });

    const scopes = [...byScope.values()]
      .map((entry) => ({
        ...entry,
        matchRate: entry.compared > 0 ? Math.round((entry.matched / entry.compared) * 100) : 0,
        topAiPartner: [...entry.partners.entries()].sort((left, right) => right[1] - left[1])[0]?.[0] ?? null,
      }))
      .sort((left, right) => right.matchRate - left.matchRate || right.compared - left.compared || right.directed - left.directed);

    return {
      scopes,
      lookup: new Map(scopes.map((entry) => [entry.scopeLabel, entry])),
      topScope: scopes[0] ?? null,
    };
  }, [filteredAuditEntries]);
  const transportFunnelAnalytics = useMemo(() => {
    const aiTransportEntries = filteredAuditEntries.filter((entry) => entry.recommendedRoute === '/transport');
    const hubOpened = aiTransportEntries.filter((entry) => didOpenTransportHub(entry));
    const partnerOpened = aiTransportEntries.filter((entry) => Boolean(getOpenedTransportPartnerLabel(entry)));
    const byPartner = new Map<
      string,
      { label: string; aiMentioned: number; recommended: number; opened: number; aiOpened: number }
    >();
    const days = Array.from({ length: 7 }, (_, index) => {
      const date = new Date();
      date.setHours(0, 0, 0, 0);
      date.setDate(date.getDate() - (6 - index));
      return {
        key: date.toISOString().slice(0, 10),
        label: formatTrendDayLabel(date),
        aiDirected: 0,
        hubOpened: 0,
        partnerOpened: 0,
      };
    });
    const byDay = new Map(days.map((day) => [day.key, day]));

    filteredTransportAuditEntries.forEach((entry) => {
      const bucket = byPartner.get(entry.appLabel) ?? {
        label: entry.appLabel,
        aiMentioned: 0,
        recommended: 0,
        opened: 0,
        aiOpened: 0,
      };
      if (entry.action === 'recommended') bucket.recommended += 1;
      if (entry.action === 'opened') bucket.opened += 1;
      byPartner.set(entry.appLabel, bucket);
    });

    aiTransportEntries.forEach((entry) => {
      const createdAt = new Date(entry.createdAt);
      if (!Number.isNaN(createdAt.getTime())) {
        createdAt.setHours(0, 0, 0, 0);
        const bucket = byDay.get(createdAt.toISOString().slice(0, 10));
        if (bucket) {
          bucket.aiDirected += 1;
          if (didOpenTransportHub(entry)) bucket.hubOpened += 1;
          if (getOpenedTransportPartnerLabel(entry)) bucket.partnerOpened += 1;
        }
      }

      const label = getOpenedTransportPartnerLabel(entry);
      if (!label) return;
      const bucket = byPartner.get(label) ?? {
        label,
        aiMentioned: 0,
        recommended: 0,
        opened: 0,
        aiOpened: 0,
      };
      bucket.aiOpened += 1;
      byPartner.set(label, bucket);
    });

    aiTransportEntries.forEach((entry) => {
      const label = getMentionedTransportPartnerLabel(entry);
      if (!label) return;
      const bucket = byPartner.get(label) ?? {
        label,
        aiMentioned: 0,
        recommended: 0,
        opened: 0,
        aiOpened: 0,
      };
      bucket.aiMentioned += 1;
      byPartner.set(label, bucket);
    });

    const partners = [...byPartner.values()]
      .map((entry) => ({
        ...entry,
        openRate: entry.recommended > 0 ? Math.round((entry.opened / entry.recommended) * 100) : 0,
        aiShare: entry.opened > 0 ? Math.round((entry.aiOpened / entry.opened) * 100) : 0,
        mentionToOpenRate: entry.aiMentioned > 0 ? Math.round((entry.aiOpened / entry.aiMentioned) * 100) : 0,
      }))
      .sort((left, right) => right.aiOpened - left.aiOpened || right.opened - left.opened || right.recommended - left.recommended);

    const topConvertedPartner = partners[0] ? ([partners[0].label, partners[0].aiOpened] as const) : null;
    const trend = days.map((day) => ({
      ...day,
      hubRate: day.aiDirected > 0 ? Math.round((day.hubOpened / day.aiDirected) * 100) : 0,
      partnerRate: day.hubOpened > 0 ? Math.round((day.partnerOpened / day.hubOpened) * 100) : 0,
    }));

    return {
      aiDirected: aiTransportEntries.length,
      hubOpened: hubOpened.length,
      partnerOpened: partnerOpened.length,
      hubOpenRate: aiTransportEntries.length > 0 ? Math.round((hubOpened.length / aiTransportEntries.length) * 100) : 0,
      partnerOpenRate:
        hubOpened.length > 0 ? Math.round((partnerOpened.length / hubOpened.length) * 100) : 0,
      topConvertedPartner,
      partners,
      trend,
      maxAiDirected: Math.max(1, ...trend.map((day) => day.aiDirected)),
    };
  }, [filteredAuditEntries, filteredTransportAuditEntries]);
  const transportManagementReport = useMemo(
    () =>
      buildTransportManagementReport(
        filteredTransportAuditEntries,
        filteredAuditEntries,
        transportPreferenceStats,
        transportPreferenceTrend.days
      ),
    [filteredAuditEntries, filteredTransportAuditEntries, transportPreferenceStats, transportPreferenceTrend.days]
  );

  const persist = useCallback(async (next: BeveiligingSettings) => {
    setSaving(true);
    try {
      await saveBeveiligingSettings(next);
    } finally {
      setSaving(false);
    }
  }, []);

  const toggleAppLock = useCallback(async () => {
    if (!canManageBeveiliging) {
      Alert.alert('Alleen-lezen', getPermissionMessage('manage_security'));
      return;
    }
    if (Platform.OS === 'web') {
      Alert.alert('Niet ondersteund op web', 'App lock met biometrie werkt alleen op iOS/Android.');
      return;
    }

    const nextValue = !settings.appLockEnabled;
    if (nextValue) {
      const ok = await canUseBiometrics();
      setBiometricsOk(ok);
      if (!ok) {
        Alert.alert('Biometrie ontbreekt', 'Stel FaceID/TouchID/toestelcode in en probeer opnieuw.');
        return;
      }
    }

    const next = { ...settings, appLockEnabled: nextValue };
    setSettings(next);
    await persist(next);
  }, [canManageBeveiliging, persist, settings]);

  const toggleCapture = useCallback(async () => {
    if (!canManageBeveiliging) {
      Alert.alert('Alleen-lezen', getPermissionMessage('manage_security'));
      return;
    }
    const nextValue = !settings.preventScreenCapture;
    const next = { ...settings, preventScreenCapture: nextValue };
    setSettings(next);
    await setCaptureBlocked(nextValue);
    await persist(next);
  }, [canManageBeveiliging, persist, settings]);

  const setTtl = useCallback(
    async (value: number) => {
      if (!canManageBeveiliging) {
        Alert.alert('Alleen-lezen', getPermissionMessage('manage_security'));
        return;
      }
      const next = { ...settings, unlockTtlMs: value };
      setSettings(next);
      await persist(next);
    },
    [canManageBeveiliging, persist, settings]
  );

  const clearAuditTrail = useCallback(async () => {
    await clearAiAuditEntries();
  }, []);

  const exportAuditCsv = useCallback(async () => {
    if (filteredAuditEntries.length === 0) {
      Alert.alert('Geen auditdata', 'Vraag eerst de echte AI op een scherm zodat er exporteerbare logregels ontstaan.');
      return;
    }

    const csv = buildAiAuditCsv(filteredAuditEntries);
    if (Platform.OS === 'web') {
      const uri = `data:text/csv;charset=utf-8,${encodeURIComponent(csv)}`;
      Linking.openURL(uri).catch(() => {
        Alert.alert('CSV export mislukt', 'Gebruik voorlopig de rapportkopie als fallback.');
      });
      return;
    }

    try {
      await Share.share({ message: csv, title: 'ai-audit.csv' });
    } catch {
      Alert.alert('CSV export mislukt', 'Delen lukte niet op dit toestel.');
    }
  }, [filteredAuditEntries]);

  const shareAuditSummary = useCallback(async () => {
    if (filteredAuditEntries.length === 0) {
      Alert.alert('Geen auditdata', 'Er is nog geen AI-auditrapport om te delen.');
      return;
    }

    if (typeof navigator !== 'undefined' && navigator.clipboard) {
      try {
        await navigator.clipboard.writeText(auditSummaryText);
        Alert.alert('Gekopieerd', 'AI auditrapport staat in je clipboard.');
        return;
      } catch {
        // fall through to share
      }
    }

    try {
      await Share.share({ message: auditSummaryText, title: 'AI auditrapport' });
    } catch {
      Alert.alert('Delen mislukt', 'Het auditrapport kon niet gedeeld worden.');
    }
  }, [auditSummaryText, filteredAuditEntries.length]);

